explanation_reveal\":\"after_selection\",\"explanation\":\"Why Rumination.\\nYour mind keeps replaying the same event without discovering new information or moving towards a solution.\\nThinking more isn\'t always thinking better.\"},{\"step_number\":3,\"key\":\"reality_check\",\"tip\":\"Ask yourself, \\\"Am I solving the problem, or simply replaying it?\\\"\",\"inputs\":[{\"field_key\":\"q1\",\"prompt\":\"1. What fact do you know for certain?\"},{\"field_key\":\"q2\",\"prompt\":\"2. What are you assuming?\"},{\"field_key\":\"q3\",\"prompt\":\"3. What evidence supports your assumption?\"},{\"field_key\":\"q4\",\"prompt\":\"4. What evidence contradicts it?\"},{\"field_key\":\"q5\",\"prompt\":\"5. If someone else described this situation, what would you tell them?\"}]},{\"step_number\":4,\"key\":\"reframe\",\"inputs\":[{\"field_key\":\"alt_explanations\",\"prompt\":\"Write at least 3 other explanations that also fit the facts.\",\"type\":\"multi_entry\",\"min_entries\":3},{\"field_key\":\"one_more_explanation\",\"prompt\":\"Can you think of one explanation that doesn\'t blame you or your child?\"}],\"reference_example\":[\"Children sometimes test boundaries at school.\",\"One incident doesn\'t describe my child\'s overall behaviour.\",\"The teacher may be informing me early so we can work together.\",\"This could be an opportunity to understand what happened before reacting.\"]},{\"step_number\":5,\"key\":\"intervention\",\"reminder\":\"There isn\'t always a perfect action.\\nThere is usually one reasonable action based on the evidence available.\",\"inputs\":[{\"field_key\":\"action\",\"prompt\":\"Based on the evidence available, what is one thoughtful action you can take?\"}],\"reference_example\":\"Speak calmly with your child to understand what happened.\\nIf needed, discuss the situation with the teacher before drawing conclusions.\\nFocus on understanding first, then deciding what action is appropriate.\"},{\"step_number\":6,\"key\":\"internalize\",\"inputs\":[{\"field_key\":\"principle\",\"prompt\":\"Complete this sentence: \\\"Today I learned that...\\\"\"}],\"reference_example\":\"Replaying the same event doesn\'t always produce new answers. Judgment improves when I move from overthinking to understanding.\"}],\"closing_reflection\":{\"prompt\":\"What situation have I been replaying without gaining any new understanding?\",\"journal_input\":{\"field_key\":\"journal\",\"prompt\":\"Optional journal entry — user may type or speak a personal reflection here (not scored).\",\"required\":false}}}', `updated_at` = '2026-09-25 16:36:12';

INSERT INTO `foundation_days` (`day_number`, `phase`, `title`, `domain`, `primary_trap`, `secondary_trap`, `content_bundle`, `created_at`, `updated_at`)
VALUES (7, 1, 'The Silent Client', 'Business', 'Mind Reading', NULL, '{\"day\":7,\"phase\":1,\"title\":\"The Silent Client\",\"domain\":\"Business\",\"mission\":\"Separate observations from interpretations.\",\"learning_objective\":\"Separate Facts from Stories\",\"difficulty\":\"Beginner-Intermediate\",\"emotional_intensity\":\"Moderate\",\"estimated_minutes\":\"3-5\",\"primary_skill\":\"Detect\",\"primary_trap\":\"Mind Reading\",\"secondary_trap\":null,\"scenario_text\":\"You sent a business proposal to an important client.\\nThey usually respond within one or two days.\\nFour days have passed.\\nThey have viewed your message but haven\'t replied.\\nYou begin wondering whether you\'ve lost the client.\",\"steps\":[{\"step_number\":1,\"key\":\"detect\",\"insight\":\"When information is missing, your brain often creates a story to fill the gap.\\nThe story may feel convincing, but it still needs evidence.\",\"inputs\":[{\"field_key\":\"facts\",\"prompt\":\"Write only the facts.\",\"multiline\":true},{\"field_key\":\"story\",\"prompt\":\"Now write the story your mind is creating.\",\"multiline\":true}],\"reference_example\":\"Fact: The client viewed my proposal four days ago and hasn\'t replied.\\nStory: The client didn\'t like my proposal and has decided not to work with me.\"},{\"step_number\":2,\"key\":\"decode\",\"prompt\":\"Which thinking trap is most likely at work?\",\"input_type\":\"single_choice\",\"options\":[{\"key\":\"mind_reading\",\"label\":\"Mind Reading\",\"definition\":\"Assuming others\' intentions without evidence.\"},{\"key\":\"fortune_telling\",\"label\":\"Fortune Telling\",\"definition\":\"Treating an unverified prediction as certain.\"},{\"key\":\"confirmation_bias\",\"label\":\"Confirmation Bias\",\"definition\":\"Only seeing details that confirm the feared story.\"}],\"correct_option_key\":\"mind_reading\",\"explanation_reveal\":\"after_selection\",\"explanation\":\"Why Mind Reading.\\nThe only confirmed fact is that the client hasn\'t replied.\\nEverything else is an interpretation.\\nWithout evidence, assuming the client\'s intentions can lead to unnecessary stress or poor decisions.\"},{\"step_number\":3,\"key\":\"reality_check\",\"tip\":\"Ask yourself, \\\"What do I know?\\\" before asking, \\\"What does it mean?\\\"\",\"inputs\":[{\"field_key\":\"q1\",\"prompt\":\"1. What fact do you know for certain?\"},{\"field_key\":\"q2\",\"prompt\":\"2. What are you assuming?\"},{\"field_key\":\"q3\",\"prompt\":\"3. What evidence supports your assumption?\"},{\"field_key\":\"q4\",\"prompt\":\"4. What evidence contradicts it?\"},{\"field_key\":\"q5\",\"prompt\":\"5. If someone else described this situation, what would you tell them?\"}]},{\"step_number\":4,\"key\":\"reframe\",\"inputs\":[{\"field_key\":\"alt_explanations\",\"prompt\":\"Write at least 3 other explanations that also fit the facts.\",\"type\":\"multi_entry\",\"min_entries\":3},{\"field_key\":\"one_more_explanation\",\"prompt\":\"Can you think of one explanation that has nothing to do with the quality of your proposal?\"}],\"reference_example\":[\"The client is reviewing the proposal internally.\",\"They are waiting for approval from another decision-maker.\",\"They became busy with other priorities.\",\"They intend to reply but haven\'t had the opportunity yet.\"]},{\"step_number\":5,\"key\":\"intervention\",\"reminder\":\"There isn\'t always a perfect action.\\nThere is usually one reasonable action based on the evidence available.\",\"inputs\":[{\"field_key\":\"action\",\"prompt\":\"Based on the evidence available, what is one thoughtful action you can take?\"}],\"reference_example\":\"Send a polite follow-up message after a reasonable interval.\\nFor example:\\n\\\"Hello, just checking whether you\'ve had a chance to review the proposal. Please let me know if you have any questions or need additional information.\\\"\\nThen allow the client time to respond.\"},{\"step_number\":6,\"key\":\"internalize\",\"inputs\":[{\"field_key\":\"principle\",\"prompt\":\"Complete this sentence: \\\"Today I learned that...\\\"\"}],\"reference_example\":\"Silence is a fact. The meaning I attach to that silence is a story until evidence proves otherwise.\"}],\"closing_reflection\":{\"prompt\":\"Where else today have I assumed someone\'s intention without actually knowing it?\",\"journal_input\":{\"field_key\":\"journal\",\"prompt\":\"Optional journal entry — user may type or speak a personal reflection here (not scored).\",\"required\":false}}}', '2026-09-25 16:36:12', '2026-09-25 16:36:12')
ON DUPLICATE KEY UPDATE `title` = 'The Silent Client', `domain` = 'Business', `primary_trap` = 'Mind Reading', `secondary_trap` = NULL, `content_bundle` = '{\"day\":7,\"phase\":1,\"title\":\"The Silent Client\",\"domain\":\"Business\",\"mission\":\"Separate observations from interpretations.\",\"learning_objective\":\"Separate Facts from Stories\",\"difficulty\":\"Beginner-Intermediate\",\"emotional_intensity\":\"Moderate\",\"estimated_minutes\":\"3-5\",\"primary_skill\":\"Detect\",\"primary_trap\":\"Mind Reading\",\"secondary_trap\":null,\"scenario_text\":\"You sent a business proposal to an important client.\\nThey usually respond within one or two days.\\nFour days have passed.\\nThey have viewed your message but haven\'t replied.\\nYou begin wondering whether you\'ve lost the client.\",\"steps\":[{\"step_number\":1,\"key\":\"detect\",\"insight\":\"When information is missing, your brain often creates a story to fill the gap.\\nThe story may feel convincing, but it still needs evidence.\",\"inputs\":[{\"field_key\":\"facts\",\"prompt\":\"Write only the facts.\",\"multiline\":true},{\"field_key\":\"story\",\"prompt\":\"Now write the story your mind is creating.\",\"multiline\":true}],\"reference_example\":\"Fact: The client viewed my proposal four days ago and hasn\'t replied.\\nStory: The client didn\'t like my proposal and has decided not to work with me.\"},{\"step_number\":2,\"key\":\"decode\",\"prompt\":\"Which thinking trap is most likely at work?\",\"input_type\":\"single_choice\",\"options\":[{\"key\":\"mind_reading\",\"label\":\"Mind Reading\",\"definition\":\"Assuming others\' intentions without evidence.\"},{\"key\":\"fortune_telling\",\"label\":\"Fortune Telling\",\"definition\":\"Treating an unverified prediction as certain.\"},{\"key\":\"confirmation_bias\",\"label\":\"Confirmation Bias\",\"definition\":\"Only seeing details that confirm the feared story.\"}],\"correct_option_key\":\"mind_reading\",\"explanation_reveal\":\"after_selection\",\"explanation\":\"Why Mind Reading.\\nThe only confirmed fact is that the client hasn\'t replied.\\nEverything else is an interpretation.\\nWithout evidence, assuming the client\'s intentions can lead to unnecessary stress or poor decisions.\"},{\"step_number\":3,\"key\":\"reality_check\",\"tip\":\"Ask yourself, \\\"What do I know?\\\" before asking, \\\"What does it mean?\\\"\",\"inputs\":[{\"field_key\":\"q1\",\"prompt\":\"1. What fact do you know for certain?\"},{\"field_key\":\"q2\",\"prompt\":\"2. What are you assuming?\"},{\"field_key\":\"q3\",\"prompt\":\"3. What evidence supports your assumption?\"},{\"field_key\":\"q4\",\"prompt\":\"4. What evidence contradicts it?\"},{\"field_key\":\"q5\",\"prompt\":\"5. If someone else described this situation, what would you tell them?\"}]},{\"step_number\":4,\"key\":\"reframe\",\"inputs\":[{\"field_key\":\"alt_explanations\",\"prompt\":\"Write at least 3 other explanations that also fit the facts.\",\"type\":\"multi_entry\",\"min_entries\":3},{\"field_key\":\"one_more_explanation\",\"prompt\":\"Can you think of one explanation that has nothing to do with the quality of your proposal?\"}],\"reference_example\":[\"The client is reviewing the proposal internally.\",\"They are waiting for approval from another decision-maker.\",\"They became busy with other priorities.\",\"They intend to reply but haven\'t had the opportunity yet.\"]},{\"step_number\":5,\"key\":\"intervention\",\"reminder\":\"There isn\'t always a perfect action.\\nThere is usually one reasonable action based on the evidence available.\",\"inputs\":[{\"field_key\":\"action\",\"prompt\":\"Based on the evidence available, what is one thoughtful action you can take?\"}],\"reference_example\":\"Send a polite follow-up message after a reasonable interval.\\nFor example:\\n\\\"Hello, just checking whether you\'ve had a chance to review the proposal. Please let me know if you have any questions or need additional information.\\\"\\nThen allow the client time to respond.\"},{\"step_number\":6,\"key\":\"internalize\",\"inputs\":[{\"field_key\":\"principle\",\"prompt\":\"Complete this sentence: \\\"Today I learned that...\\\"\"}],\"reference_example\":\"Silence is a fact. The meaning I attach to that silence is a story until evidence proves otherwise.\"}],\"closing_reflection\":{\"prompt\":\"Where else today have I assumed someone\'s intention without actually knowing it?\",\"journal_input\":{\"field_key\":\"journal\",\"prompt\":\"Optional journal entry — user may type or speak a personal reflection here (not scored).\",\"required\":false}}}', `updated_at` = '2026-09-25 16:36:12';

INSERT INTO `foundation_days` (`day_number`, `phase`, `title`, `domain`, `primary_trap`, `secondary_trap`, `content_bundle`, `created_at`, `updated_at`)
VALUES (8, 1, 'The First Offer', 'Finance', 'Validation Seeking', NULL, '{\"day\":8,\"phase\":1,\"title\":\"The First Offer\",\"domain\":\"Finance\",\"mission\":\"Don\'t let someone else\'s opinion become your only measure of your worth.\",\"learning_objective\":\"Recognize Thinking Traps\",\"difficulty\":\"Beginner-Intermediate\",\"emotional_intensity\":\"Moderate\",\"estimated_minutes\":\"3-5\",\"primary_skill\":\"Decode\",\"primary_trap\":\"Validation Seeking\",\"secondary_trap\":null,\"scenario_text\":\"After several interview rounds, you finally receive a job offer.\\nThe salary offered is lower than you expected.\\nBefore reviewing the complete role or responsibilities, you immediately begin wondering:\\n\\\"Maybe this is all I\'m worth.\\\"\",\"steps\":[{\"step_number\":1,\"key\":\"detect\",\"insight\":\"One person\'s opinion or one offer doesn\'t define your value.\\nIt is only one piece of information.\",\"inputs\":[{\"field_key\":\"facts\",\"prompt\":\"Write only the facts.\",\"multiline\":true},{\"field_key\":\"story\",\"prompt\":\"Now write the story your mind is creating.\",\"multiline\":true}],\"reference_example\":\"Fact: I received a job offer with a lower salary than I expected.\\nStory: The company thinks I\'m not valuable enough.\"},{\"step_number\":2,\"key\":\"decode\",\"prompt\":\"Which thinking trap is most likely at work?\",\"input_type\":\"single_choice\",\"options\":[{\"key\":\"validation_seeking\",\"label\":\"Validation Seeking\",\"definition\":\"Heavy reliance on immediate external acknowledgment.\"},{\"key\":\"all_or_nothing\",\"label\":\"All-or-Nothing Thinking\",\"definition\":\"Treating a minor gap as total failure.\"},{\"key\":\"confirmation_bias\",\"label\":\"Confirmation Bias\",\"definition\":\"Only seeing details that confirm the feared story.\"}],\"correct_option_key\":\"validation_seeking\",\"explanation_reveal\":\"after_selection\",\"explanation\":\"Why Validation Seeking.\\nInstead of viewing the offer as one negotiation point, your mind has started using it as proof of your personal worth.\\nExternal feedback is information.\\nIt isn\'t your identity.\"},{\"step_number\":3,\"key\":\"reality_check\",\"tip\":\"Feedback informs you. It doesn\'t define you.\",\"inputs\":[{\"field_key\":\"q1\",\"prompt\":\"1. What fact do you know for certain?\"},{\"field_key\":\"q2\",\"prompt\":\"2. What are you assuming?\"},{\"field_key\":\"q3\",\"prompt\":\"3. What evidence supports your assumption?\"},{\"field_key\":\"q4\",\"prompt\":\"4. What evidence contradicts it?\"},{\"field_key\":\"q5\",\"prompt\":\"5. If someone else described this situation, what would you tell them?\"}]},{\"step_number\":4,\"key\":\"reframe\",\"inputs\":[{\"field_key\":\"alt_explanations\",\"prompt\":\"Write at least 3 other explanations that also fit the facts.\",\"type\":\"multi_entry\",\"min_entries\":3},{\"field_key\":\"one_more_explanation\",\"prompt\":\"Can you think of one explanation that has nothing to do with your abilities?\"}],\"reference_example\":[\"The company may have salary bands for the role.\",\"The offer may simply be their opening position.\",\"There may be room for negotiation.\",\"Budget constraints may influence the offer.\"]},{\"step_number\":5,\"key\":\"intervention\",\"reminder\":\"There isn\'t always a perfect action.\\nThere is usually one reasonable action based on the evidence available.\",\"inputs\":[{\"field_key\":\"action\",\"prompt\":\"Based on the evidence available, what is one thoughtful action you can take?\"}],\"reference_example\":\"Review the complete offer objectively.\\nResearch market salaries.\\nIf appropriate, negotiate respectfully based on your experience and the value you bring rather than reacting emotionally to the first number.\"},{\"step_number\":6,\"key\":\"internalize\",\"inputs\":[{\"field_key\":\"principle\",\"prompt\":\"Complete this sentence: \\\"Today I learned that...\\\"\"}],\"reference_example\":\"External feedback provides information. It does not determine my worth.\"}],\"closing_reflection\":{\"prompt\":\"Where else have I allowed someone else\'s opinion to define how I see myself?\",\"journal_input\":{\"field_key\":\"journal\",\"prompt\":\"Optional journal entry — user may type or speak a personal reflection here (not scored).\",\"required\":false}}}', '2026-09-25 16:36:12', '2026-09-25 16:36:12')
ON DUPLICATE KEY UPDATE `title` = 'The First Offer', `domain` = 'Finance', `primary_trap` = 'Validation Seeking', `secondary_trap` = NULL, `content_bundle` = '{\"day\":8,\"phase\":1,\"title\":\"The First Offer\",\"domain\":\"Finance\",\"mission\":\"Don\'t let someone else\'s opinion become your only measure of your worth.\",\"learning_objective\":\"Recognize Thinking Traps\",\"difficulty\":\"Beginner-Intermediate\",\"emotional_intensity\":\"Moderate\",\"estimated_minutes\":\"3-5\",\"primary_skill\":\"Decode\",\"primary_trap\":\"Validation Seeking\",\"secondary_trap\":null,\"scenario_text\":\"After several interview rounds, you finally receive a job offer.\\nThe salary offered is lower than you expected.\\nBefore reviewing the complete role or responsibilities, you immediately begin wondering:\\n\\\"Maybe this is all I\'m worth.\\\"\",\"steps\":[{\"step_number\":1,\"key\":\"detect\",\"insight\":\"One person\'s opinion or one offer doesn\'t define your value.\\nIt is only one piece of information.\",\"inputs\":[{\"field_key\":\"facts\",\"prompt\":\"Write only the facts.\",\"multiline\":true},{\"field_key\":\"story\",\"prompt\":\"Now write the story your mind is creating.\",\"multiline\":true}],\"reference_example\":\"Fact: I received a job offer with a lower salary than I expected.\\nStory: The company thinks I\'m not valuable enough.\"},{\"step_number\":2,\"key\":\"decode\",\"prompt\":\"Which thinking trap is most likely at work?\",\"input_type\":\"single_choice\",\"options\":[{\"key\":\"validation_seeking\",\"label\":\"Validation Seeking\",\"definition\":\"Heavy reliance on immediate external acknowledgment.\"},{\"key\":\"all_or_nothing\",\"label\":\"All-or-Nothing Thinking\",\"definition\":\"Treating a minor gap as total failure.\"},{\"key\":\"confirmation_bias\",\"label\":\"Confirmation Bias\",\"definition\":\"Only seeing details that confirm the feared story.\"}],\"correct_option_key\":\"validation_seeking\",\"explanation_reveal\":\"after_selection\",\"explanation\":\"Why Validation Seeking.\\nInstead of viewing the offer as one negotiation point, your mind has started using it as proof of your personal worth.\\nExternal feedback is information.\\nIt isn\'t your identity.\"},{\"step_number\":3,\"key\":\"reality_check\",\"tip\":\"Feedback informs you. It doesn\'t define you.\",\"inputs\":[{\"field_key\":\"q1\",\"prompt\":\"1. What fact do you know for certain?\"},{\"field_key\":\"q2\",\"prompt\":\"2. What are you assuming?\"},{\"field_key\":\"q3\",\"prompt\":\"3. What evidence supports your assumption?\"},{\"field_key\":\"q4\",\"prompt\":\"4. What evidence contradicts it?\"},{\"field_key\":\"q5\",\"prompt\":\"5. If someone else described this situation, what would you tell them?\"}]},{\"step_number\":4,\"key\":\"reframe\",\"inputs\":[{\"field_key\":\"alt_explanations\",\"prompt\":\"Write at least 3 other explanations that also fit the facts.\",\"type\":\"multi_entry\",\"min_entries\":3},{\"field_key\":\"one_more_explanation\",\"prompt\":\"Can you think of one explanation that has nothing to do with your abilities?\"}],\"reference_example\":[\"The company may have salary bands for the role.\",\"The offer may simply be their opening position.\",\"There may be room for negotiation.\",\"Budget constraints may influence the offer.\"]},{\"step_number\":5,\"key\":\"intervention\",\"reminder\":\"There isn\'t always a perfect action.\\nThere is usually one reasonable action based on the evidence available.\",\"inputs\":[{\"field_key\":\"action\",\"prompt\":\"Based on the evidence available, what is one thoughtful action you can take?\"}],\"reference_example\":\"Review the complete offer objectively.\\nResearch market salaries.\\nIf appropriate, negotiate respectfully based on your experience and the value you bring rather than reacting emotionally to the first number.\"},{\"step_number\":6,\"key\":\"internalize\",\"inputs\":[{\"field_key\":\"principle\",\"prompt\":\"Complete this sentence: \\\"Today I learned that...\\\"\"}],\"reference_example\":\"External feedback provides information. It does not determine my worth.\"}],\"closing_reflection\":{\"prompt\":\"Where else have I allowed someone else\'s opinion to define how I see myself?\",\"journal_input\":{\"field_key\":\"journal\",\"prompt\":\"Optional journal entry — user may type or speak a personal reflection here (not scored).\",\"required\":false}}}', `updated_at` = '2026-09-25 16:36:12';

INSERT INTO `foundation_days` (`day_number`, `phase`, `title`, `domain`, `primary_trap`, `secondary_trap`, `content_bundle`, `created_at`, `updated_at`)
VALUES (9, 1, 'Left Out of the Meeting', 'Workplace', 'Confirmation Bias', NULL, '{\"day\":9,\"phase\":1,\"title\":\"Left Out of the Meeting\",\"domain\":\"Workplace\",\"mission\":\"Verify before you conclude.\",\"learning_objective\":\"Test Assumptions with Evidence\",\"difficulty\":\"Intermediate\",\"emotional_intensity\":\"Moderate\",\"estimated_minutes\":\"3-5\",\"primary_skill\":\"Reality Check\",\"primary_trap\":\"Confirmation Bias\",\"secondary_trap\":null,\"scenario_text\":\"You arrive at work and notice that several colleagues are discussing a meeting that happened yesterday.\\nYou weren\'t invited.\\nNo one has spoken to you about it.\\nYou immediately begin wondering whether you are being excluded from important decisions.\",\"steps\":[{\"step_number\":1,\"key\":\"detect\",\"insight\":\"When information is incomplete, your brain quickly tries to explain why.\\nAn explanation isn\'t the same as evidence.\",\"inputs\":[{\"field_key\":\"facts\",\"prompt\":\"Write only the facts.\",\"multiline\":true},{\"field_key\":\"story\",\"prompt\":\"Now write the story your mind is creating.\",\"multiline\":true}],\"reference_example\":\"Fact: A meeting took place yesterday, and I wasn\'t present.\\nStory: I\'m being excluded because my manager no longer values my contribution.\"},{\"step_number\":2,\"key\":\"decode\",\"prompt\":\"Which thinking trap is most likely at work?\",\"input_type\":\"single_choice\",\"options\":[{\"key\":\"confirmation_bias\",\"label\":\"Confirmation Bias\",\"definition\":\"Only seeing details that confirm the feared story.\"},{\"key\":\"mind_reading\",\"label\":\"Mind Reading\",\"definition\":\"Assuming others\' intentions without evidence.\"},{\"key\":\"fortune_telling\",\"label\":\"Fortune Telling\",\"definition\":\"Treating an unverified prediction as certain.\"}],\"correct_option_key\":\"confirmation_bias\",\"explanation_reveal\":\"after_selection\",\"explanation\":\"Why Confirmation Bias.\\nOnce you believe you\'re being excluded, your mind starts looking for evidence that supports that belief.\\nAt the same time, it ignores other possible explanations.\"},{\"step_number\":3,\"key\":\"reality_check\",\"tip\":\"Missing information is not evidence. Gather facts before filling the gaps.\",\"inputs\":[{\"field_key\":\"q1\",\"prompt\":\"1. What fact do you know for certain?\"},{\"field_key\":\"q2\",\"prompt\":\"2. What are you assuming?\"},{\"field_key\":\"q3\",\"prompt\":\"3. What evidence supports your assumption?\"},{\"field_key\":\"q4\",\"prompt\":\"4. What evidence contradicts it?\"},{\"field_key\":\"q5\",\"prompt\":\"5. What information is still missing before you can reach a conclusion?\"}]},{\"step_number\":4,\"key\":\"reframe\",\"inputs\":[{\"field_key\":\"alt_explanations\",\"prompt\":\"Write at least 3 other explanations that also fit the facts.\",\"type\":\"multi_entry\",\"min_entries\":3},{\"field_key\":\"one_more_explanation\",\"prompt\":\"Can you think of one explanation that doesn\'t involve anyone intentionally excluding you?\"}],\"reference_example\":[\"The meeting involved a project you aren\'t currently assigned to.\",\"It was arranged at short notice.\",\"Someone assumed another colleague had already informed you.\",\"A follow-up discussion may still be planned.\"]},{\"step_number\":5,\"key\":\"intervention\",\"reminder\":\"There isn\'t always a perfect action.\\nThere is usually one reasonable action based on the evidence available.\",\"inputs\":[{\"field_key\":\"action\",\"prompt\":\"Based on the evidence available, what is one thoughtful action you can take?\"}],\"reference_example\":\"Rather than assuming the reason, ask your manager or a colleague:\\n\\\"I heard there was a meeting yesterday. Could you help me understand what it was about and whether there\'s anything I should know?\\\"\\nSeek information before interpreting the situation.\"},{\"step_number\":6,\"key\":\"internalize\",\"inputs\":[{\"field_key\":\"principle\",\"prompt\":\"Complete this sentence: \\\"Today I learned that...\\\"\"}],\"reference_example\":\"When information is missing, my first responsibility is to gather facts—not create explanations.\"}],\"closing_reflection\":{\"prompt\":\"Where else have I filled gaps in information with my own explanation instead of asking for facts?\",\"journal_input\":{\"field_key\":\"journal\",\"prompt\":\"Optional journal entry — user may type or speak a personal reflection here (not scored).\",\"required\":false}}}', '2026-09-25 16:36:12', '2026-09-25 16:36:12')
ON DUPLICATE KEY UPDATE `title` = 'Left Out of the Meeting', `domain` = 'Workplace', `primary_trap` = 'Confirmation Bias', `secondary_trap` = NULL, `content_bundle` = '{\"day\":9,\"phase\":1,\"title\":\"Left Out of the Meeting\",\"domain\":\"Workplace\",\"mission\":\"Verify before you conclude.\",\"learning_objective\":\"Test Assumptions with Evidence\",\"difficulty\":\"Intermediate\",\"emotional_intensity\":\"Moderate\",\"estimated_minutes\":\"3-5\",\"primary_skill\":\"Reality Check\",\"primary_trap\":\"Confirmation Bias\",\"secondary_trap\":null,\"scenario_text\":\"You arrive at work and notice that several colleagues are discussing a meeting that happened yesterday.\\nYou weren\'t invited.\\nNo one has spoken to you about it.\\nYou immediately begin wondering whether you are being excluded from important decisions.\",\"steps\":[{\"step_number\":1,\"key\":\"detect\",\"insight\":\"When information is incomplete, your brain quickly tries to explain why.\\nAn explanation isn\'t the same as evidence.\",\"inputs\":[{\"field_key\":\"facts\",\"prompt\":\"Write only the facts.\",\"multiline\":true},{\"field_key\":\"story\",\"prompt\":\"Now write the story your mind is creating.\",\"multiline\":true}],\"reference_example\":\"Fact: A meeting took place yesterday, and I wasn\'t present.\\nStory: I\'m being excluded because my manager no longer values my contribution.\"},{\"step_number\":2,\"key\":\"decode\",\"prompt\":\"Which thinking trap is most likely at work?\",\"input_type\":\"single_choice\",\"options\":[{\"key\":\"confirmation_bias\",\"label\":\"Confirmation Bias\",\"definition\":\"Only seeing details that confirm the feared story.\"},{\"key\":\"mind_reading\",\"label\":\"Mind Reading\",\"definition\":\"Assuming others\' intentions without evidence.\"},{\"key\":\"fortune_telling\",\"label\":\"Fortune Telling\",\"definition\":\"Treating an unverified prediction as certain.\"}],\"correct_option_key\":\"confirmation_bias\",\"explanation_reveal\":\"after_selection\",\"explanation\":\"Why Confirmation Bias.\\nOnce you believe you\'re being excluded, your mind starts looking for evidence that supports that belief.\\nAt the same time, it ignores other possible explanations.\"},{\"step_number\":3,\"key\":\"reality_check\",\"tip\":\"Missing information is not evidence. Gather facts before filling the gaps.\",\"inputs\":[{\"field_key\":\"q1\",\"prompt\":\"1. What fact do you know for certain?\"},{\"field_key\":\"q2\",\"prompt\":\"2. What are you assuming?\"},{\"field_key\":\"q3\",\"prompt\":\"3. What evidence supports your assumption?\"},{\"field_key\":\"q4\",\"prompt\":\"4. What evidence contradicts it?\"},{\"field_key\":\"q5\",\"prompt\":\"5. What information is still missing before you can reach a conclusion?\"}]},{\"step_number\":4,\"key\":\"reframe\",\"inputs\":[{\"field_key\":\"alt_explanations\",\"prompt\":\"Write at least 3 other explanations that also fit the facts.\",\"type\":\"multi_entry\",\"min_entries\":3},{\"field_key\":\"one_more_explanation\",\"prompt\":\"Can you think of one explanation that doesn\'t involve anyone intentionally excluding you?\"}],\"reference_example\":[\"The meeting involved a project you aren\'t currently assigned to.\",\"It was arranged at short notice.\",\"Someone assumed another colleague had already informed you.\",\"A follow-up discussion may still be planned.\"]},{\"step_number\":5,\"key\":\"intervention\",\"reminder\":\"There isn\'t always a perfect action.\\nThere is usually one reasonable action based on the evidence available.\",\"inputs\":[{\"field_key\":\"action\",\"prompt\":\"Based on the evidence available, what is one thoughtful action you can take?\"}],\"reference_example\":\"Rather than assuming the reason, ask your manager or a colleague:\\n\\\"I heard there was a meeting yesterday. Could you help me understand what it was about and whether there\'s anything I should know?\\\"\\nSeek information before interpreting the situation.\"},{\"step_number\":6,\"key\":\"internalize\",\"inputs\":[{\"field_key\":\"principle\",\"prompt\":\"Complete this sentence: \\\"Today I learned that...\\\"\"}],\"reference_example\":\"When information is missing, my first responsibility is to gather facts—not create explanations.\"}],\"closing_reflection\":{\"prompt\":\"Where else have I filled gaps in information with my own explanation instead of asking for facts?\",\"journal_input\":{\"field_key\":\"journal\",\"prompt\":\"Optional journal entry — user may type or speak a personal reflection here (not scored).\",\"required\":false}}}', `updated_at` = '2026-09-25 16:36:12';

INSERT INTO `foundation_days` (`day_number`, `phase`, `title`, `domain`, `primary_trap`, `secondary_trap`, `content_bundle`, `created_at`, `updated_at`)
VALUES (10, 1, 'Cancelled Dinner', 'Relationships', 'Fortune Telling', NULL, '{\"day\":10,\"phase\":1,\"title\":\"Cancelled Dinner\",\"domain\":\"Relationships\",\"mission\":\"One event can have many explanations.\",\"learning_objective\":\"Generate Alternative Explanations\",\"difficulty\":\"Intermediate\",\"emotional_intensity\":\"Moderate\",\"estimated_minutes\":\"3-5\",\"primary_skill\":\"Reframe\",\"primary_trap\":\"Fortune Telling\",\"secondary_trap\":null,\"scenario_text\":\"You and your partner planned to have dinner together after work.\\nAn hour before meeting, they send a message:\\n\\\"I\'m really sorry. Can we do this another day?\\\"\\nNo explanation is given.\\nYou immediately begin thinking that something is wrong with the relationship.\",\"steps\":[{\"step_number\":1,\"key\":\"detect\",\"insight\":\"A cancelled plan is a fact.\\nThe meaning you attach to it is an interpretation.\",\"inputs\":[{\"field_key\":\"facts\",\"prompt\":\"Write only the facts.\",\"multiline\":true},{\"field_key\":\"story\",\"prompt\":\"Now write the story your mind is creating.\",\"multiline\":true}],\"reference_example\":\"Fact: My partner cancelled our dinner plans and asked to meet another day.\\nStory: Our relationship is changing, and they don\'t want to spend time with me anymore.\"},{\"step_number\":2,\"key\":\"decode\",\"prompt\":\"Which thinking trap is most likely at work?\",\"input_type\":\"single_choice\",\"options\":[{\"key\":\"fortune_telling\",\"label\":\"Fortune Telling\",\"definition\":\"Treating an unverified prediction as certain.\"},{\"key\":\"mind_reading\",\"label\":\"Mind Reading\",\"definition\":\"Assuming others\' intentions without evidence.\"},{\"key\":\"catastrophizing\",\"label\":\"Catastrophizing\",\"definition\":\"Assuming the absolute worst outcome.\"}],\"correct_option_key\":\"fortune_telling\",\"explanation_reveal\":\"after_selection\",\"explanation\":\"Why Fortune Telling.\\nYour mind has taken one cancelled plan and predicted what it believes will happen next.\\nNothing in the situation confirms that prediction.\"},{\"step_number\":3,\"key\":\"reality_check\",\"tip\":\"Don\'t confuse today\'s event with tomorrow\'s prediction.\",\"inputs\":[{\"field_key\":\"q1\",\"prompt\":\"1. What fact do you know for certain?\"},{\"field_key\":\"q2\",\"prompt\":\"2. What are you assuming?\"},{\"field_key\":\"q3\",\"prompt\":\"3. What evidence supports your assumption?\"},{\"field_key\":\"q4\",\"prompt\":\"4. What evidence contradicts it?\"},{\"field_key\":\"q5\",\"prompt\":\"5. If this happened to a close friend, what advice would you give them?\"}]},{\"step_number\":4,\"key\":\"reframe\",\"inputs\":[{\"field_key\":\"alt_explanations\",\"prompt\":\"Write at least 3 other explanations that also fit the facts.\",\"type\":\"multi_entry\",\"min_entries\":3},{\"field_key\":\"one_more_explanation\",\"prompt\":\"Can you think of one explanation that assumes good intent instead of bad intent?\"}],\"reference_example\":[\"Something urgent came up at work.\",\"They aren\'t feeling well.\",\"A family responsibility unexpectedly arose.\",\"They genuinely want to meet another day when they can give you their full attention.\"]},{\"step_number\":5,\"key\":\"intervention\",\"reminder\":\"There isn\'t always a perfect action.\\nThere is usually one reasonable action based on the evidence available.\",\"inputs\":[{\"field_key\":\"action\",\"prompt\":\"Based on the evidence available, what is one thoughtful action you can take?\"}],\"reference_example\":\"Reply calmly and acknowledge the change of plans.\\nFor example:\\n\\\"No problem. Let me know when you\'re free, and we\'ll plan another day.\\\"\\nIf the pattern continues repeatedly over time, then gather more information before reaching a conclusion.\"},{\"step_number\":6,\"key\":\"internalize\",\"inputs\":[{\"field_key\":\"principle\",\"prompt\":\"Complete this sentence: \\\"Today I learned that...\\\"\"}],\"reference_example\":\"One cancelled plan does not predict the future of a relationship.\"}],\"closing_reflection\":{\"prompt\":\"Where else have I treated one event as proof of what will happen next?\",\"journal_input\":{\"field_key\":\"journal\",\"prompt\":\"Optional journal entry — user may type or speak a personal reflection here (not scored).\",\"required\":false}}}', '2026-09-25 16:36:12', '2026-09-25 16:36:12')
