,\"explanation_reveal\":\"after_selection\",\"explanation\":\"Why Sunk Cost Fallacy.\\nThe decision is being influenced by what you\'ve already invested rather than by whether continuing still makes sense.\\nPast investment is real.\\nIt shouldn\'t automatically determine future action.\"},{\"step_number\":3,\"key\":\"reality_check\",\"tip\":\"Ask yourself, \\\"Am I deciding based on the future or trying to justify the past?\\\"\",\"inputs\":[{\"field_key\":\"q1\",\"prompt\":\"1. What fact do you know for certain?\"},{\"field_key\":\"q2\",\"prompt\":\"2. What are you assuming?\"},{\"field_key\":\"q3\",\"prompt\":\"3. If you had not already invested the time and money, would you still choose this course today?\"},{\"field_key\":\"q4\",\"prompt\":\"4. What evidence suggests continuing is the best option?\"},{\"field_key\":\"q5\",\"prompt\":\"5. What evidence suggests changing direction might be reasonable?\"}]},{\"step_number\":4,\"key\":\"reframe\",\"inputs\":[{\"field_key\":\"alt_explanations\",\"prompt\":\"Write at least 3 other explanations that also fit the facts.\",\"type\":\"multi_entry\",\"min_entries\":3},{\"field_key\":\"one_more_explanation\",\"prompt\":\"Can you think of one benefit of changing direction instead of continuing automatically?\"}],\"reference_example\":[\"The knowledge I\'ve already gained still has value.\",\"Stopping now doesn\'t erase what I\'ve learned.\",\"My interests and goals may have changed.\",\"It\'s reasonable to redirect my time toward something that better fits my future.\"]},{\"step_number\":5,\"key\":\"intervention\",\"reminder\":\"There isn\'t always a perfect action.\\nThere is usually one reasonable action based on the evidence available.\",\"inputs\":[{\"field_key\":\"action\",\"prompt\":\"Based on the evidence available, what is one thoughtful action you can take?\"}],\"reference_example\":\"Review your current career goals.\\nIf the course still supports those goals, complete it with intention.\\nIf it no longer aligns, make a deliberate decision rather than continuing only because you\'ve already invested time and money.\"},{\"step_number\":6,\"key\":\"internalize\",\"inputs\":[{\"field_key\":\"principle\",\"prompt\":\"Complete this sentence: \\\"Today I learned that...\\\"\"}],\"reference_example\":\"Past investment deserves respect, but future decisions should be guided by future value.\"}],\"closing_reflection\":{\"prompt\":\"What decision in my life am I continuing mainly because of what I\'ve already invested?\",\"journal_input\":{\"field_key\":\"journal\",\"prompt\":\"Optional journal entry — user may type or speak a personal reflection here (not scored).\",\"required\":false}}}', `updated_at` = '2026-09-25 16:36:12';

INSERT INTO `foundation_days` (`day_number`, `phase`, `title`, `domain`, `primary_trap`, `secondary_trap`, `content_bundle`, `created_at`, `updated_at`)
VALUES (12, 1, 'The Forgotten Birthday', 'Family', 'All-or-Nothing Thinking', NULL, '{\"day\":12,\"phase\":1,\"title\":\"The Forgotten Birthday\",\"domain\":\"Family\",\"mission\":\"One mistake doesn\'t define the whole story.\",\"learning_objective\":\"Internalize the Thinking Process\",\"difficulty\":\"Intermediate\",\"emotional_intensity\":\"Moderate\",\"estimated_minutes\":\"3-5\",\"primary_skill\":\"Internalize\",\"primary_trap\":\"All-or-Nothing Thinking\",\"secondary_trap\":null,\"scenario_text\":\"Your brother forgets your birthday.\\nHe doesn\'t call.\\nHe doesn\'t send a message.\\nBy the end of the day, you begin thinking:\\n\\\"He doesn\'t care about me anymore.\\\"\",\"steps\":[{\"step_number\":1,\"key\":\"detect\",\"insight\":\"One event may be disappointing.\\nThat doesn\'t automatically describe the entire relationship.\",\"inputs\":[{\"field_key\":\"facts\",\"prompt\":\"Write only the facts.\",\"multiline\":true},{\"field_key\":\"story\",\"prompt\":\"Now write the story your mind is creating.\",\"multiline\":true}],\"reference_example\":\"Fact: My brother didn\'t wish me on my birthday.\\nStory: He doesn\'t care about me anymore.\"},{\"step_number\":2,\"key\":\"decode\",\"prompt\":\"Which thinking trap is most likely at work?\",\"input_type\":\"single_choice\",\"options\":[{\"key\":\"all_or_nothing\",\"label\":\"All-or-Nothing Thinking\",\"definition\":\"Treating a minor gap as total failure.\"},{\"key\":\"mind_reading\",\"label\":\"Mind Reading\",\"definition\":\"Assuming others\' intentions without evidence.\"},{\"key\":\"emotional_reasoning\",\"label\":\"Emotional Reasoning\",\"definition\":\"Treating a feeling as proof of reality.\"}],\"correct_option_key\":\"all_or_nothing\",\"explanation_reveal\":\"after_selection\",\"explanation\":\"Why All-or-Nothing Thinking.\\nYour mind has taken one disappointing event and used it to make a sweeping conclusion about the entire relationship.\\nOne event rarely tells the complete story.\"},{\"step_number\":3,\"key\":\"reality_check\",\"tip\":\"Don\'t let one moment define the whole relationship.\",\"inputs\":[{\"field_key\":\"q1\",\"prompt\":\"1. What fact do you know for certain?\"},{\"field_key\":\"q2\",\"prompt\":\"2. What are you assuming?\"},{\"field_key\":\"q3\",\"prompt\":\"3. Does this one event represent the entire relationship?\"},{\"field_key\":\"q4\",\"prompt\":\"4. What evidence suggests your relationship has been positive at other times?\"},{\"field_key\":\"q5\",\"prompt\":\"5. If someone else described this situation, what would you tell them?\"}]},{\"step_number\":4,\"key\":\"reframe\",\"inputs\":[{\"field_key\":\"alt_explanations\",\"prompt\":\"Write at least 3 other explanations that also fit the facts.\",\"type\":\"multi_entry\",\"min_entries\":3},{\"field_key\":\"one_more_explanation\",\"prompt\":\"Can you think of one memory that contradicts your current conclusion?\"}],\"reference_example\":[\"He genuinely forgot the date.\",\"He has been unusually busy.\",\"Something unexpected may have happened that day.\",\"He may realize later and apologize.\"]},{\"step_number\":5,\"key\":\"intervention\",\"reminder\":\"There isn\'t always a perfect action.\\nThere is usually one reasonable action based on the evidence available.\",\"inputs\":[{\"field_key\":\"action\",\"prompt\":\"Based on the evidence available, what is one thoughtful action you can take?\"}],\"reference_example\":\"Rather than assuming the relationship has changed, speak with your brother when the opportunity arises.\\nIf it continues to bother you, express how you felt without making assumptions about his intentions.\\nFor example:\\n\\\"I missed hearing from you on my birthday. I just wanted to check if everything is okay.\\\"\"},{\"step_number\":6,\"key\":\"internalize\",\"inputs\":[{\"field_key\":\"principle\",\"prompt\":\"Complete this sentence: \\\"Today I learned that...\\\"\"}],\"reference_example\":\"One disappointing moment does not define an entire relationship. Judgment requires seeing the bigger picture.\"}],\"closing_reflection\":{\"prompt\":\"Where else have I allowed one event to shape my opinion of an entire person or situation?\",\"journal_input\":{\"field_key\":\"journal\",\"prompt\":\"Optional journal entry — user may type or speak a personal reflection here (not scored).\",\"required\":false}}}', '2026-09-25 16:36:12', '2026-09-25 16:36:12')
ON DUPLICATE KEY UPDATE `title` = 'The Forgotten Birthday', `domain` = 'Family', `primary_trap` = 'All-or-Nothing Thinking', `secondary_trap` = NULL, `content_bundle` = '{\"day\":12,\"phase\":1,\"title\":\"The Forgotten Birthday\",\"domain\":\"Family\",\"mission\":\"One mistake doesn\'t define the whole story.\",\"learning_objective\":\"Internalize the Thinking Process\",\"difficulty\":\"Intermediate\",\"emotional_intensity\":\"Moderate\",\"estimated_minutes\":\"3-5\",\"primary_skill\":\"Internalize\",\"primary_trap\":\"All-or-Nothing Thinking\",\"secondary_trap\":null,\"scenario_text\":\"Your brother forgets your birthday.\\nHe doesn\'t call.\\nHe doesn\'t send a message.\\nBy the end of the day, you begin thinking:\\n\\\"He doesn\'t care about me anymore.\\\"\",\"steps\":[{\"step_number\":1,\"key\":\"detect\",\"insight\":\"One event may be disappointing.\\nThat doesn\'t automatically describe the entire relationship.\",\"inputs\":[{\"field_key\":\"facts\",\"prompt\":\"Write only the facts.\",\"multiline\":true},{\"field_key\":\"story\",\"prompt\":\"Now write the story your mind is creating.\",\"multiline\":true}],\"reference_example\":\"Fact: My brother didn\'t wish me on my birthday.\\nStory: He doesn\'t care about me anymore.\"},{\"step_number\":2,\"key\":\"decode\",\"prompt\":\"Which thinking trap is most likely at work?\",\"input_type\":\"single_choice\",\"options\":[{\"key\":\"all_or_nothing\",\"label\":\"All-or-Nothing Thinking\",\"definition\":\"Treating a minor gap as total failure.\"},{\"key\":\"mind_reading\",\"label\":\"Mind Reading\",\"definition\":\"Assuming others\' intentions without evidence.\"},{\"key\":\"emotional_reasoning\",\"label\":\"Emotional Reasoning\",\"definition\":\"Treating a feeling as proof of reality.\"}],\"correct_option_key\":\"all_or_nothing\",\"explanation_reveal\":\"after_selection\",\"explanation\":\"Why All-or-Nothing Thinking.\\nYour mind has taken one disappointing event and used it to make a sweeping conclusion about the entire relationship.\\nOne event rarely tells the complete story.\"},{\"step_number\":3,\"key\":\"reality_check\",\"tip\":\"Don\'t let one moment define the whole relationship.\",\"inputs\":[{\"field_key\":\"q1\",\"prompt\":\"1. What fact do you know for certain?\"},{\"field_key\":\"q2\",\"prompt\":\"2. What are you assuming?\"},{\"field_key\":\"q3\",\"prompt\":\"3. Does this one event represent the entire relationship?\"},{\"field_key\":\"q4\",\"prompt\":\"4. What evidence suggests your relationship has been positive at other times?\"},{\"field_key\":\"q5\",\"prompt\":\"5. If someone else described this situation, what would you tell them?\"}]},{\"step_number\":4,\"key\":\"reframe\",\"inputs\":[{\"field_key\":\"alt_explanations\",\"prompt\":\"Write at least 3 other explanations that also fit the facts.\",\"type\":\"multi_entry\",\"min_entries\":3},{\"field_key\":\"one_more_explanation\",\"prompt\":\"Can you think of one memory that contradicts your current conclusion?\"}],\"reference_example\":[\"He genuinely forgot the date.\",\"He has been unusually busy.\",\"Something unexpected may have happened that day.\",\"He may realize later and apologize.\"]},{\"step_number\":5,\"key\":\"intervention\",\"reminder\":\"There isn\'t always a perfect action.\\nThere is usually one reasonable action based on the evidence available.\",\"inputs\":[{\"field_key\":\"action\",\"prompt\":\"Based on the evidence available, what is one thoughtful action you can take?\"}],\"reference_example\":\"Rather than assuming the relationship has changed, speak with your brother when the opportunity arises.\\nIf it continues to bother you, express how you felt without making assumptions about his intentions.\\nFor example:\\n\\\"I missed hearing from you on my birthday. I just wanted to check if everything is okay.\\\"\"},{\"step_number\":6,\"key\":\"internalize\",\"inputs\":[{\"field_key\":\"principle\",\"prompt\":\"Complete this sentence: \\\"Today I learned that...\\\"\"}],\"reference_example\":\"One disappointing moment does not define an entire relationship. Judgment requires seeing the bigger picture.\"}],\"closing_reflection\":{\"prompt\":\"Where else have I allowed one event to shape my opinion of an entire person or situation?\",\"journal_input\":{\"field_key\":\"journal\",\"prompt\":\"Optional journal entry — user may type or speak a personal reflection here (not scored).\",\"required\":false}}}', `updated_at` = '2026-09-25 16:36:12';

INSERT INTO `foundation_days` (`day_number`, `phase`, `title`, `domain`, `primary_trap`, `secondary_trap`, `content_bundle`, `created_at`, `updated_at`)
VALUES (13, 1, 'Waiting for the Test Report', 'Health', 'Emotional Reasoning', 'Catastrophizing', '{\"day\":13,\"phase\":1,\"title\":\"Waiting for the Test Report\",\"domain\":\"Health\",\"mission\":\"A feeling is a signal, not a conclusion.\",\"learning_objective\":\"Separate Facts from Stories\",\"difficulty\":\"Intermediate\",\"emotional_intensity\":\"Moderate\",\"estimated_minutes\":\"3-5\",\"primary_skill\":\"Detect (Third Learning Cycle)\",\"primary_trap\":\"Emotional Reasoning\",\"secondary_trap\":\"Catastrophizing\",\"scenario_text\":\"Your doctor advises you to undergo a routine blood test.\\nThe report will be available in two days.\\nOn your way home, you begin feeling anxious.\\nBy evening, you find yourself thinking:\\n\\\"If I\'m this worried, something must be seriously wrong.\\\"\",\"steps\":[{\"step_number\":1,\"key\":\"detect\",\"insight\":\"Your emotions provide information about how you feel.\\nThey do not provide evidence about what is true.\",\"inputs\":[{\"field_key\":\"facts\",\"prompt\":\"Write only the facts.\",\"multiline\":true},{\"field_key\":\"story\",\"prompt\":\"Now write the story your mind is creating.\",\"multiline\":true}],\"reference_example\":\"Fact: My doctor advised a blood test, and the report will be ready in two days.\\nStory: Because I feel anxious, the report will probably show something serious.\"},{\"step_number\":2,\"key\":\"decode\",\"prompt\":\"Which thinking trap is most likely at work?\",\"input_type\":\"single_choice\",\"options\":[{\"key\":\"emotional_reasoning\",\"label\":\"Emotional Reasoning\",\"definition\":\"Treating a feeling as proof of reality.\"},{\"key\":\"catastrophizing\",\"label\":\"Catastrophizing\",\"definition\":\"Assuming the absolute worst outcome.\"},{\"key\":\"fortune_telling\",\"label\":\"Fortune Telling\",\"definition\":\"Treating an unverified prediction as certain.\"}],\"correct_option_key\":\"emotional_reasoning\",\"explanation_reveal\":\"after_selection\",\"explanation\":\"Why Emotional Reasoning.\\nFeeling anxious while waiting is understandable.\\nThe mistake happens when anxiety becomes proof that something bad has happened.\\nYour feeling is real.\\nYour conclusion still requires evidence.\"},{\"step_number\":3,\"key\":\"reality_check\",\"tip\":\"Feeling uncertain is normal. Treating uncertainty as evidence is the trap.\",\"inputs\":[{\"field_key\":\"q1\",\"prompt\":\"1. What fact do you know for certain?\"},{\"field_key\":\"q2\",\"prompt\":\"2. What are you feeling right now?\"},{\"field_key\":\"q3\",\"prompt\":\"3. Are your feelings the same as evidence?\"},{\"field_key\":\"q4\",\"prompt\":\"4. What evidence do you actually have today?\"},{\"field_key\":\"q5\",\"prompt\":\"5. What information are you still waiting for?\"}]},{\"step_number\":4,\"key\":\"reframe\",\"inputs\":[{\"field_key\":\"alt_explanations\",\"prompt\":\"Write at least 3 other explanations that also fit the facts.\",\"type\":\"multi_entry\",\"min_entries\":3},{\"field_key\":\"one_more_explanation\",\"prompt\":\"Can you think of one explanation that is based on facts rather than feelings?\"}],\"reference_example\":[\"Routine blood tests are commonly recommended.\",\"The doctor may simply be gathering more information.\",\"Most test results do not indicate serious illness.\",\"Waiting for results naturally creates uncertainty.\"]},{\"step_number\":5,\"key\":\"intervention\",\"reminder\":\"There isn\'t always a perfect action.\\nThere is usually one reasonable action based on the evidence available.\",\"inputs\":[{\"field_key\":\"action\",\"prompt\":\"Based on the evidence available, what is one thoughtful action you can take?\"}],\"reference_example\":\"Wait for the test results before reaching any conclusions.\\nContinue your normal plans in the meantime — a feeling is not a result, and only the result should change your decision.\"},{\"step_number\":6,\"key\":\"internalize\",\"inputs\":[{\"field_key\":\"principle\",\"prompt\":\"Complete this sentence: \\\"Today I learned that...\\\"\"}],\"reference_example\":\"Feeling anxious doesn\'t tell me what the result will be. Feelings deserve attention, but evidence deserves my decisions.\"}],\"closing_reflection\":{\"prompt\":\"When was the last time I treated a feeling as if it were evidence?\",\"journal_input\":{\"field_key\":\"journal\",\"prompt\":\"Optional journal entry — user may type or speak a personal reflection here (not scored).\",\"required\":false}}}', '2026-09-25 16:36:12', '2026-09-25 16:36:12')
ON DUPLICATE KEY UPDATE `title` = 'Waiting for the Test Report', `domain` = 'Health', `primary_trap` = 'Emotional Reasoning', `secondary_trap` = 'Catastrophizing', `content_bundle` = '{\"day\":13,\"phase\":1,\"title\":\"Waiting for the Test Report\",\"domain\":\"Health\",\"mission\":\"A feeling is a signal, not a conclusion.\",\"learning_objective\":\"Separate Facts from Stories\",\"difficulty\":\"Intermediate\",\"emotional_intensity\":\"Moderate\",\"estimated_minutes\":\"3-5\",\"primary_skill\":\"Detect (Third Learning Cycle)\",\"primary_trap\":\"Emotional Reasoning\",\"secondary_trap\":\"Catastrophizing\",\"scenario_text\":\"Your doctor advises you to undergo a routine blood test.\\nThe report will be available in two days.\\nOn your way home, you begin feeling anxious.\\nBy evening, you find yourself thinking:\\n\\\"If I\'m this worried, something must be seriously wrong.\\\"\",\"steps\":[{\"step_number\":1,\"key\":\"detect\",\"insight\":\"Your emotions provide information about how you feel.\\nThey do not provide evidence about what is true.\",\"inputs\":[{\"field_key\":\"facts\",\"prompt\":\"Write only the facts.\",\"multiline\":true},{\"field_key\":\"story\",\"prompt\":\"Now write the story your mind is creating.\",\"multiline\":true}],\"reference_example\":\"Fact: My doctor advised a blood test, and the report will be ready in two days.\\nStory: Because I feel anxious, the report will probably show something serious.\"},{\"step_number\":2,\"key\":\"decode\",\"prompt\":\"Which thinking trap is most likely at work?\",\"input_type\":\"single_choice\",\"options\":[{\"key\":\"emotional_reasoning\",\"label\":\"Emotional Reasoning\",\"definition\":\"Treating a feeling as proof of reality.\"},{\"key\":\"catastrophizing\",\"label\":\"Catastrophizing\",\"definition\":\"Assuming the absolute worst outcome.\"},{\"key\":\"fortune_telling\",\"label\":\"Fortune Telling\",\"definition\":\"Treating an unverified prediction as certain.\"}],\"correct_option_key\":\"emotional_reasoning\",\"explanation_reveal\":\"after_selection\",\"explanation\":\"Why Emotional Reasoning.\\nFeeling anxious while waiting is understandable.\\nThe mistake happens when anxiety becomes proof that something bad has happened.\\nYour feeling is real.\\nYour conclusion still requires evidence.\"},{\"step_number\":3,\"key\":\"reality_check\",\"tip\":\"Feeling uncertain is normal. Treating uncertainty as evidence is the trap.\",\"inputs\":[{\"field_key\":\"q1\",\"prompt\":\"1. What fact do you know for certain?\"},{\"field_key\":\"q2\",\"prompt\":\"2. What are you feeling right now?\"},{\"field_key\":\"q3\",\"prompt\":\"3. Are your feelings the same as evidence?\"},{\"field_key\":\"q4\",\"prompt\":\"4. What evidence do you actually have today?\"},{\"field_key\":\"q5\",\"prompt\":\"5. What information are you still waiting for?\"}]},{\"step_number\":4,\"key\":\"reframe\",\"inputs\":[{\"field_key\":\"alt_explanations\",\"prompt\":\"Write at least 3 other explanations that also fit the facts.\",\"type\":\"multi_entry\",\"min_entries\":3},{\"field_key\":\"one_more_explanation\",\"prompt\":\"Can you think of one explanation that is based on facts rather than feelings?\"}],\"reference_example\":[\"Routine blood tests are commonly recommended.\",\"The doctor may simply be gathering more information.\",\"Most test results do not indicate serious illness.\",\"Waiting for results naturally creates uncertainty.\"]},{\"step_number\":5,\"key\":\"intervention\",\"reminder\":\"There isn\'t always a perfect action.\\nThere is usually one reasonable action based on the evidence available.\",\"inputs\":[{\"field_key\":\"action\",\"prompt\":\"Based on the evidence available, what is one thoughtful action you can take?\"}],\"reference_example\":\"Wait for the test results before reaching any conclusions.\\nContinue your normal plans in the meantime — a feeling is not a result, and only the result should change your decision.\"},{\"step_number\":6,\"key\":\"internalize\",\"inputs\":[{\"field_key\":\"principle\",\"prompt\":\"Complete this sentence: \\\"Today I learned that...\\\"\"}],\"reference_example\":\"Feeling anxious doesn\'t tell me what the result will be. Feelings deserve attention, but evidence deserves my decisions.\"}],\"closing_reflection\":{\"prompt\":\"When was the last time I treated a feeling as if it were evidence?\",\"journal_input\":{\"field_key\":\"journal\",\"prompt\":\"Optional journal entry — user may type or speak a personal reflection here (not scored).\",\"required\":false}}}', `updated_at` = '2026-09-25 16:36:12';

INSERT INTO `foundation_days` (`day_number`, `phase`, `title`, `domain`, `primary_trap`, `secondary_trap`, `content_bundle`, `created_at`, `updated_at`)
VALUES (14, 1, 'No Interview Feedback', 'Career', 'Fortune Telling', NULL, '{\"day\":14,\"phase\":1,\"title\":\"No Interview Feedback\",\"domain\":\"Career\",\"mission\":\"Predictions are not evidence.\",\"learning_objective\":\"Recognize Thinking Traps\",\"difficulty\":\"Intermediate\",\"emotional_intensity\":\"Moderate\",\"estimated_minutes\":\"3-5\",\"primary_skill\":\"Decode (Third Learning Cycle)\",\"primary_trap\":\"Fortune Telling\",\"secondary_trap\":null,\"scenario_text\":\"You attend a job interview that goes well.\\nThe interviewer tells you they\'ll get back to you within five working days.\\nSeven days pass.\\nYou haven\'t received any email or phone call.\\nYou begin thinking:\\n\\\"I didn\'t get the job.\\\"\",\"steps\":[{\"step_number\":1,\"key\":\"detect\",\"insight\":\"When answers are delayed, your mind often creates one.\\nA prediction may feel convincing, but it isn\'t evidence.\",\"inputs\":[{\"field_key\":\"facts\",\"prompt\":\"Write only the facts.\",\"multiline\":true},{\"field_key\":\"story\",\"prompt\":\"Now write the story your mind is creating.\",\"multiline\":true}],\"reference_example\":\"Fact: It\'s been seven days since my interview, and I haven\'t received any update.\\nStory: I wasn\'t selected for the role.\"},{\"step_number\":2,\"key\":\"decode\",\"prompt\":\"Which thinking trap is most likely at work?\",\"input_type\":\"single_choice\",\"options\":[{\"key\":\"fortune_telling\",\"label\":\"Fortune Telling\",\"definition\":\"Treating an unverified prediction as certain.\"},{\"key\":\"catastrophizing\",\"label\":\"Catastrophizing\",\"definition\":\"Assuming the absolute worst outcome.\"},{\"key\":\"mind_reading\",\"label\":\"Mind Reading\",\"definition\":\"Assuming others\' intentions without evidence.\"}],\"correct_option_key\":\"fortune_telling\",\"explanation_reveal\":\"after_selection\",\"explanation\":\"Why Fortune Telling.\\nNo decision has been communicated.\\nYour mind has filled the silence with a prediction and accepted it as fact.\"},{\"step_number\":3,\"key\":\"reality_check\",\"tip\":\"A delay is information. It is not a decision.\",\"inputs\":[{\"field_key\":\"q1\",\"prompt\":\"1. What fact do you know for certain?\"},{\"field_key\":\"q2\",\"prompt\":\"2. What are you assuming?\"},{\"field_key\":\"q3\",\"prompt\":\"3. What evidence supports your assumption?\"},{\"field_key\":\"q4\",\"prompt\":\"4. What evidence contradicts it?\"},{\"field_key\":\"q5\",\"prompt\":\"5. What other explanations could account for the delay?\"}]},{\"step_number\":4,\"key\":\"reframe\",\"inputs\":[{\"field_key\":\"alt_explanations\",\"prompt\":\"Write at least 3 other explanations that also fit the facts.\",\"type\":\"multi_entry\",\"min_entries\":3},{\"field_key\":\"one_more_explanation\",\"prompt\":\"Can you think of one explanation that has nothing to do with your interview performance?\"}],\"reference_example\":[\"The hiring team is interviewing other candidates.\",\"The hiring manager is unavailable.\",\"Internal approvals are taking longer than expected.\",\"The recruitment process has been delayed.\"]},{\"step_number\":5,\"key\":\"intervention\",\"reminder\":\"There isn\'t always a perfect action.\\nThere is usually one reasonable action based on the evidence available.\",\"inputs\":[{\"field_key\":\"action\",\"prompt\":\"Based on the evidence available, what is one thoughtful action you can take?\"}],\"reference_example\":\"Wait a reasonable amount of time and send a polite follow-up email.\\nFor example:\\n\\\"I hope you\'re doing well. I wanted to follow up regarding my interview and check if there are any updates. Thank you for your time and consideration.\\\"\\nContinue applying for other opportunities instead of waiting for one outcome.\"},{\"step_number\":6,\"key\":\"internalize\",\"inputs\":[{\"field_key\":\"principle\",\"prompt\":\"Complete this sentence: \\\"Today I learned that...\\\"\"}],\"reference_example\":\"A delayed response is not the same as a negative response. Predictions should never replace evidence.\"}],\"closing_reflection\":{\"prompt\":\"Where else have I mistaken uncertainty for certainty?\",\"journal_input\":{\"field_key\":\"journal\",\"prompt\":\"Optional journal entry — user may type or speak a personal reflection here (not scored).\",\"required\":false}}}', '2026-09-25 16:36:12', '2026-09-25 16:36:12')
ON DUPLICATE KEY UPDATE `title` = 'No Interview Feedback', `domain` = 'Career', `primary_trap` = 'Fortune Telling', `secondary_trap` = NULL, `content_bundle` = '{\"day\":14,\"phase\":1,\"title\":\"No Interview Feedback\",\"domain\":\"Career\",\"mission\":\"Predictions are not evidence.\",\"learning_objective\":\"Recognize Thinking Traps\",\"difficulty\":\"Intermediate\",\"emotional_intensity\":\"Moderate\",\"estimated_minutes\":\"3-5\",\"primary_skill\":\"Decode (Third Learning Cycle)\",\"primary_trap\":\"Fortune Telling\",\"secondary_trap\":null,\"scenario_text\":\"You attend a job interview that goes well.\\nThe interviewer tells you they\'ll get back to you within five working days.\\nSeven days pass.\\nYou haven\'t received any email or phone call.\\nYou begin thinking:\\n\\\"I didn\'t get the job.\\\"\",\"steps\":[{\"step_number\":1,\"key\":\"detect\",\"insight\":\"When answers are delayed, your mind often creates one.\\nA prediction may feel convincing, but it isn\'t evidence.\",\"inputs\":[{\"field_key\":\"facts\",\"prompt\":\"Write only the facts.\",\"multiline\":true},{\"field_key\":\"story\",\"prompt\":\"Now write the story your mind is creating.\",\"multiline\":true}],\"reference_example\":\"Fact: It\'s been seven days since my interview, and I haven\'t received any update.\\nStory: I wasn\'t selected for the role.\"},{\"step_number\":2,\"key\":\"decode\",\"prompt\":\"Which thinking trap is most likely at work?\",\"input_type\":\"single_choice\",\"options\":[{\"key\":\"fortune_telling\",\"label\":\"Fortune Telling\",\"definition\":\"Treating an unverified prediction as certain.\"},{\"key\":\"catastrophizing\",\"label\":\"Catastrophizing\",\"definition\":\"Assuming the absolute worst outcome.\"},{\"key\":\"mind_reading\",\"label\":\"Mind Reading\",\"definition\":\"Assuming others\' intentions without evidence.\"}],\"correct_option_key\":\"fortune_telling\",\"explanation_reveal\":\"after_selection\",\"explanation\":\"Why Fortune Telling.\\nNo decision has been communicated.\\nYour mind has filled the silence with a prediction and accepted it as fact.\"},{\"step_number\":3,\"key\":\"reality_check\",\"tip\":\"A delay is information. It is not a decision.\",\"inputs\":[{\"field_key\":\"q1\",\"prompt\":\"1. What fact do you know for certain?\"},{\"field_key\":\"q2\",\"prompt\":\"2. What are you assuming?\"},{\"field_key\":\"q3\",\"prompt\":\"3. What evidence supports your assumption?\"},{\"field_key\":\"q4\",\"prompt\":\"4. What evidence contradicts it?\"},{\"field_key\":\"q5\",\"prompt\":\"5. What other explanations could account for the delay?\"}]},{\"step_number\":4,\"key\":\"reframe\",\"inputs\":[{\"field_key\":\"alt_explanations\",\"prompt\":\"Write at least 3 other explanations that also fit the facts.\",\"type\":\"multi_entry\",\"min_entries\":3},{\"field_key\":\"one_more_explanation\",\"prompt\":\"Can you think of one explanation that has nothing to do with your interview performance?\"}],\"reference_example\":[\"The hiring team is interviewing other candidates.\",\"The hiring manager is unavailable.\",\"Internal approvals are taking longer than expected.\",\"The recruitment process has been delayed.\"]},{\"step_number\":5,\"key\":\"intervention\",\"reminder\":\"There isn\'t always a perfect action.\\nThere is usually one reasonable action based on the evidence available.\",\"inputs\":[{\"field_key\":\"action\",\"prompt\":\"Based on the evidence available, what is one thoughtful action you can take?\"}],\"reference_example\":\"Wait a reasonable amount of time and send a polite follow-up email.\\nFor example:\\n\\\"I hope you\'re doing well. I wanted to follow up regarding my interview and check if there are any updates. Thank you for your time and consideration.\\\"\\nContinue applying for other opportunities instead of waiting for one outcome.\"},{\"step_number\":6,\"key\":\"internalize\",\"inputs\":[{\"field_key\":\"principle\",\"prompt\":\"Complete this sentence: \\\"Today I learned that...\\\"\"}],\"reference_example\":\"A delayed response is not the same as a negative response. Predictions should never replace evidence.\"}],\"closing_reflection\":{\"prompt\":\"Where else have I mistaken uncertainty for certainty?\",\"journal_input\":{\"field_key\":\"journal\",\"prompt\":\"Optional journal entry — user may type or speak a personal reflection here (not scored).\",\"required\":false}}}', `updated_at` = '2026-09-25 16:36:12';

INSERT INTO `foundation_days` (`day_number`, `phase`, `title`, `domain`, `primary_trap`, `secondary_trap`, `content_bundle`, `created_at`, `updated_at`)
VALUES (15, 1, 'The Closed Door', 'Parenting', 'Mind Reading', 'Emotional Reasoning (possible)', '{\"day\":15,\"phase\":1,\"title\":\"The Closed Door\",\"domain\":\"Parenting\",\"mission\":\"Don\'t assume you know the reason.\",\"learning_objective\":\"Test Assumptions with Evidence\",\"difficulty\":\"Intermediate\",\"emotional_intensity\":\"Moderate\",\"estimated_minutes\":\"3-5\",\"primary_skill\":\"Reality Check (Third Learning Cycle)\",\"primary_trap\":\"Mind Reading\",\"secondary_trap\":\"Emotional Reasoning (possible)\",\"scenario_text\":\"Over the past week, your teenage son has been spending more time alone in his room.\\nHe closes the door after returning from school.\\nHe joins the family for meals but speaks very little.\\nYou begin thinking:\\n\\\"He doesn\'t want to talk to me anymore.\\\"\",\"steps\":[{\"step_number\":1,\"key\":\"detect\",\"insight\":\"A behaviour is something you observe.\\nThe reason behind that behaviour is often a story your mind creates.\",\"inputs\":[{\"field_key\":\"facts\",\"prompt\":\"Write only the facts.\",\"multiline\":true},{\"field_key\":\"story\",\"prompt\":\"Now write the story your mind is creating.\",\"multiline\":true}],\"reference_example\":\"Fact: My son has been spending more time in his room and speaking less than usual.\\nStory: He is upset with me and no longer wants to talk to me.\"},{\"step_number\":2,\"key\":\"decode\",\"prompt\":\"Which thinking trap is most likely at work?\",\"input_type\":\"single_choice\",\"options\":[{\"key\":\"mind_reading\",\"label\":\"Mind Reading\",\"definition\":\"Assuming others\' intentions without evidence.\"},{\"key\":\"emotional_reasoning\",\"label\":\"Emotional Reasoning\",\"definition\":\"Treating a feeling as proof of reality.\"},{\"key\":\"fortune_telling\",\"label\":\"Fortune Telling\",\"definition\":\"Treating an unverified prediction as certain.\"}],\"correct_option_key\":\"mind_reading\",\"explanation_reveal\":\"after_selection\",\"explanation\":\"Why Mind Reading.\\nThe behaviour is visible.\\nThe intention behind the behaviour is unknown.\\nWithout evidence, assuming you know what someone else is thinking can lead to misunderstandings.\"},{\"step_number\":3,\"key\":\"reality_check\",\"tip\":\"Understanding begins with curiosity, not assumptions.\",\"inputs\":[{\"field_key\":\"q1\",\"prompt\":\"1. What fact do you know for certain?\"},{\"field_key\":\"q2\",\"prompt\":\"2. What are you assuming?\"},{\"field_key\":\"q3\",\"prompt\":\"3. What evidence supports your assumption?\"},{\"field_key\":\"q4\",\"prompt\":\"4. What evidence contradicts it?\"},{\"field_key\":\"q5\",\"prompt\":\"5. Have you asked your child what is happening, or are you assuming you already know?\"}]},{\"step_number\":4,\"key\":\"reframe\",\"inputs\":[{\"field_key\":\"alt_explanations\",\"prompt\":\"Write at least 3 other explanations that also fit the facts.\",\"type\":\"multi_entry\",\"min_entries\":3},{\"field_key\":\"one_more_explanation\",\"prompt\":\"Can you think of one explanation that has nothing to do with your relationship?\"}],\"reference_example\":[\"He may be tired after school.\",\"He may be dealing with academic pressure.\",\"He may simply want some personal space.\",\"Something at school may be bothering him.\",\"This could be a temporary phase.\"]},{\"step_number\":5,\"key\":\"intervention\",\"reminder\":\"There isn\'t always a perfect action.\\nThere is usually one reasonable action based on the evidence available.\",\"inputs\":[{\"field_key\":\"action\",\"prompt\":\"Based on the evidence available, what is one thoughtful action you can take?\"}],\"reference_example\":\"Choose a calm moment to talk.\\nInstead of asking,\\n\\\"Why are you avoiding me?\\\"\\nTry asking,\\n\\\"I\'ve noticed you\'ve been spending more time in your room lately. Is everything okay?\\\"\\nListen first.\\nInterpret later.\"},{\"step_number\":6,\"key\":\"internalize\",\"inputs\":[{\"field_key\":\"principle\",\"prompt\":\"Complete this sentence: \\\"Today I learned that...\\\"\"}],\"reference_example\":\"Observing someone\'s behaviour is different from knowing the reason behind it. Understanding begins by asking, not assuming.\"}],\"closing_reflection\":{\"prompt\":\"Where else in my life have I assumed someone\'s intention without first asking them?\",\"journal_input\":{\"field_key\":\"journal\",\"prompt\":\"Optional journal entry — user may type or speak a personal reflection here (not scored).\",\"required\":false}}}', '2026-09-25 16:36:12', '2026-09-25 16:36:12')
ON DUPLICATE KEY UPDATE `title` = 'The Closed Door', `domain` = 'Parenting', `primary_trap` = 'Mind Reading', `secondary_trap` = 'Emotional Reasoning (possible)', `content_bundle` = '{\"day\":15,\"phase\":1,\"title\":\"The Closed Door\",\"domain\":\"Parenting\",\"mission\":\"Don\'t assume you know the reason.\",\"learning_objective\":\"Test Assumptions with Evidence\",\"difficulty\":\"Intermediate\",\"emotional_intensity\":\"Moderate\",\"estimated_minutes\":\"3-5\",\"primary_skill\":\"Reality Check (Third Learning Cycle)\",\"primary_trap\":\"Mind Reading\",\"secondary_trap\":\"Emotional Reasoning (possible)\",\"scenario_text\":\"Over the past week, your teenage son has been spending more time alone in his room.\\nHe closes the door after returning from school.\\nHe joins the family for meals but speaks very little.\\nYou begin thinking:\\n\\\"He doesn\'t want to talk to me anymore.\\\"\",\"steps\":[{\"step_number\":1,\"key\":\"detect\",\"insight\":\"A behaviour is something you observe.\\nThe reason behind that behaviour is often a story your mind creates.\",\"inputs\":[{\"field_key\":\"facts\",\"prompt\":\"Write only the facts.\",\"multiline\":true},{\"field_key\":\"story\",\"prompt\":\"Now write the story your mind is creating.\",\"multiline\":true}],\"reference_example\":\"Fact: My son has been spending more time in his room and speaking less than usual.\\nStory: He is upset with me and no longer wants to talk to me.\"},{\"step_number\":2,\"key\":\"decode\",\"prompt\":\"Which thinking trap is most likely at work?\",\"input_type\":\"single_choice\",\"options\":[{\"key\":\"mind_reading\",\"label\":\"Mind Reading\",\"definition\":\"Assuming others\' intentions without evidence.\"},{\"key\":\"emotional_reasoning\",\"label\":\"Emotional Reasoning\",\"definition\":\"Treating a feeling as proof of reality.\"},{\"key\":\"fortune_telling\",\"label\":\"Fortune Telling\",\"definition\":\"Treating an unverified prediction as certain.\"}],\"correct_option_key\":\"mind_reading\",\"explanation_reveal\":\"after_selection\",\"explanation\":\"Why Mind Reading.\\nThe behaviour is visible.\\nThe intention behind the behaviour is unknown.\\nWithout evidence, assuming you know what someone else is thinking can lead to misunderstandings.\"},{\"step_number\":3,\"key\":\"reality_check\",\"tip\":\"Understanding begins with curiosity, not assumptions.\",\"inputs\":[{\"field_key\":\"q1\",\"prompt\":\"1. What fact do you know for certain?\"},{\"field_key\":\"q2\",\"prompt\":\"2. What are you assuming?\"},{\"field_key\":\"q3\",\"prompt\":\"3. What evidence supports your assumption?\"},{\"field_key\":\"q4\",\"prompt\":\"4. What evidence contradicts it?\"},{\"field_key\":\"q5\",\"prompt\":\"5. Have you asked your child what is happening, or are you assuming you already know?\"}]},{\"step_number\":4,\"key\":\"reframe\",\"inputs\":[{\"field_key\":\"alt_explanations\",\"prompt\":\"Write at least 3 other explanations that also fit the facts.\",\"type\":\"multi_entry\",\"min_entries\":3},{\"field_key\":\"one_more_explanation\",\"prompt\":\"Can you think of one explanation that has nothing to do with your relationship?\"}],\"reference_example\":[\"He may be tired after school.\",\"He may be dealing with academic pressure.\",\"He may simply want some personal space.\",\"Something at school may be bothering him.\",\"This could be a temporary phase.\"]},{\"step_number\":5,\"key\":\"intervention\",\"reminder\":\"There isn\'t always a perfect action.\\nThere is usually one reasonable action based on the evidence available.\",\"inputs\":[{\"field_key\":\"action\",\"prompt\":\"Based on the evidence available, what is one thoughtful action you can take?\"}],\"reference_example\":\"Choose a calm moment to talk.\\nInstead of asking,\\n\\\"Why are you avoiding me?\\\"\\nTry asking,\\n\\\"I\'ve noticed you\'ve been spending more time in your room lately. Is everything okay?\\\"\\nListen first.\\nInterpret later.\"},{\"step_number\":6,\"key\":\"internalize\",\"inputs\":[{\"field_key\":\"principle\",\"prompt\":\"Complete this sentence: \\\"Today I learned that...\\\"\"}],\"reference_example\":\"Observing someone\'s behaviour is different from knowing the reason behind it. Understanding begins by asking, not assuming.\"}],\"closing_reflection\":{\"prompt\":\"Where else in my life have I assumed someone\'s intention without first asking them?\",\"journal_input\":{\"field_key\":\"journal\",\"prompt\":\"Optional journal entry — user may type or speak a personal reflection here (not scored).\",\"required\":false}}}', `updated_at` = '2026-09-25 16:36:12';

INSERT INTO `foundation_days` (`day_number`, `phase`, `title`, `domain`, `primary_trap`, `secondary_trap`, `content_bundle`, `created_at`, `updated_at`)
VALUES (16, 1, 'Falling Sales', 'Business', 'Confirmation Bias', 'Catastrophizing (possible)', '{\"day\":16,\"phase\":1,\"title\":\"Falling Sales\",\"domain\":\"Business\",\"mission\":\"Don\'t let one explanation become the only explanation.\",\"learning_objective\":\"Generate Alternative Explanations\",\"difficulty\":\"Intermediate\",\"emotional_intensity\":\"Moderate\",\"estimated_minutes\":\"3-5\",\"primary_skill\":\"Reframe (Third Learning Cycle)\",\"primary_trap\":\"Confirmation Bias\",\"secondary_trap\":\"Catastrophizing (possible)\",\"scenario_text\":\"You own a small business.\\nSales have declined for the past two months.\\nA friend tells you,\\n\\\"Customers don\'t like your product anymore.\\\"\\nFor the rest of the day, you begin noticing only things that seem to support that conclusion.\",\"steps\":[{\"step_number\":1,\"key\":\"detect\",\"insight\":\"When your mind accepts one explanation, it naturally starts searching for evidence that supports it.\\nThat doesn\'t mean it\'s the correct explanation.\",\"inputs\":[{\"field_key\":\"facts\",\"prompt\":\"Write only the facts.\",\"multiline\":true},{\"field_key\":\"story\",\"prompt\":\"Now write the story your mind is creating.\",\"multiline\":true}],\"reference_example\":\"Fact: Sales have declined for the past two months.\\nStory: Customers no longer like my product, and my business is failing.\"},{\"step_number\":2,\"key\":\"decode\",\"prompt\":\"Which thinking trap is most likely at work?\",\"input_type\":\"single_choice\",\"options\":[{\"key\":\"confirmation_bias\",\"label\":\"Confirmation Bias\",\"definition\":\"Only seeing details that confirm the feared story.\"},{\"key\":\"catastrophizing\",\"label\":\"Catastrophizing\",\"definition\":\"Assuming the absolute worst outcome.\"},{\"key\":\"fortune_telling\",\"label\":\"Fortune Telling\",\"definition\":\"Treating an unverified prediction as certain.\"}],\"correct_option_key\":\"confirmation_bias\",\"explanation_reveal\":\"after_selection\",\"explanation\":\"Why Confirmation Bias.\\nOnce you accepted the idea that customers no longer liked your product, your attention shifted toward information that supported that belief.\\nAt the same time, you stopped looking for alternative explanations.\"},{\"step_number\":3,\"key\":\"reality_check\",\"tip\":\"Strong judgments are built on complete evidence—not selective evidence.\",\"inputs\":[{\"field_key\":\"q1\",\"prompt\":\"1. What fact do you know for certain?\"},{\"field_key\":\"q2\",\"prompt\":\"2. What are you assuming?\"},{\"field_key\":\"q3\",\"prompt\":\"3. What evidence supports your assumption?\"},{\"field_key\":\"q4\",\"prompt\":\"4. What evidence challenges your assumption?\"},{\"field_key\":\"q5\",\"prompt\":\"5. What information do you still need before deciding why sales have fallen?\"}]},{\"step_number\":4,\"key\":\"reframe\",\"inputs\":[{\"field_key\":\"alt_explanations\",\"prompt\":\"Write at least 3 other explanations that also fit the facts.\",\"type\":\"multi_entry\",\"min_entries\":3},{\"field_key\":\"one_more_explanation\",\"prompt\":\"Can you think of one explanation that has nothing to do with the quality of your product?\"}],\"reference_example\":[\"Demand may be lower because of seasonal changes.\",\"A new competitor may have entered the market.\",\"Customers may not know about recent improvements to the product.\",\"Marketing activity may have decreased.\",\"Economic conditions may have affected customer spending.\"]},{\"step_number\":5,\"key\":\"intervention\",\"reminder\":\"There isn\'t always a perfect action.\\nThere is usually one reasonable action based on the evidence available.\",\"inputs\":[{\"field_key\":\"action\",\"prompt\":\"Based on the evidence available, what is one thoughtful action you can take?\"}],\"reference_example\":\"Instead of immediately changing the product, gather more information.\\nReview sales data, speak with customers, compare previous months, and identify patterns before deciding what action to take.\"},{\"step_number\":6,\"key\":\"internalize\",\"inputs\":[{\"field_key\":\"principle\",\"prompt\":\"Complete this sentence: \\\"Today I learned that...\\\"\"}],\"reference_example\":\"The first explanation that comes to mind isn\'t always the correct one. Good judgment requires looking for evidence that both supports and challenges my conclusion.\"}],\"closing_reflection\":{\"prompt\":\"Where else in my life have I accepted one explanation without looking for alternatives?\",\"journal_input\":{\"field_key\":\"journal\",\"prompt\":\"Optional journal entry — user may type or speak a personal reflection here (not scored).\",\"required\":false}}}', '2026-09-25 16:36:12', '2026-09-25 16:36:12')
ON DUPLICATE KEY UPDATE `title` = 'Falling Sales', `domain` = 'Business', `primary_trap` = 'Confirmation Bias', `secondary_trap` = 'Catastrophizing (possible)', `content_bundle` = '{\"day\":16,\"phase\":1,\"title\":\"Falling Sales\",\"domain\":\"Business\",\"mission\":\"Don\'t let one explanation become the only explanation.\",\"learning_objective\":\"Generate Alternative Explanations\",\"difficulty\":\"Intermediate\",\"emotional_intensity\":\"Moderate\",\"estimated_minutes\":\"3-5\",\"primary_skill\":\"Reframe (Third Learning Cycle)\",\"primary_trap\":\"Confirmation Bias\",\"secondary_trap\":\"Catastrophizing (possible)\",\"scenario_text\":\"You own a small business.\\nSales have declined for the past two months.\\nA friend tells you,\\n\\\"Customers don\'t like your product anymore.\\\"\\nFor the rest of the day, you begin noticing only things that seem to support that conclusion.\",\"steps\":[{\"step_number\":1,\"key\":\"detect\",\"insight\":\"When your mind accepts one explanation, it naturally starts searching for evidence that supports it.\\nThat doesn\'t mean it\'s the correct explanation.\",\"inputs\":[{\"field_key\":\"facts\",\"prompt\":\"Write only the facts.\",\"multiline\":true},{\"field_key\":\"story\",\"prompt\":\"Now write the story your mind is creating.\",\"multiline\":true}],\"reference_example\":\"Fact: Sales have declined for the past two months.\\nStory: Customers no longer like my product, and my business is failing.\"},{\"step_number\":2,\"key\":\"decode\",\"prompt\":\"Which thinking trap is most likely at work?\",\"input_type\":\"single_choice\",\"options\":[{\"key\":\"confirmation_bias\",\"label\":\"Confirmation Bias\",\"definition\":\"Only seeing details that confirm the feared story.\"},{\"key\":\"catastrophizing\",\"label\":\"Catastrophizing\",\"definition\":\"Assuming the absolute worst outcome.\"},{\"key\":\"fortune_telling\",\"label\":\"Fortune Telling\",\"definition\":\"Treating an unverified prediction as certain.\"}],\"correct_option_key\":\"confirmation_bias\",\"explanation_reveal\":\"after_selection\",\"explanation\":\"Why Confirmation Bias.\\nOnce you accepted the idea that customers no longer liked your product, your attention shifted toward information that supported that belief.\\nAt the same time, you stopped looking for alternative explanations.\"},{\"step_number\":3,\"key\":\"reality_check\",\"tip\":\"Strong judgments are built on complete evidence—not selective evidence.\",\"inputs\":[{\"field_key\":\"q1\",\"prompt\":\"1. What fact do you know for certain?\"},{\"field_key\":\"q2\",\"prompt\":\"2. What are you assuming?\"},{\"field_key\":\"q3\",\"prompt\":\"3. What evidence supports your assumption?\"},{\"field_key\":\"q4\",\"prompt\":\"4. What evidence challenges your assumption?\"},{\"field_key\":\"q5\",\"prompt\":\"5. What information do you still need before deciding why sales have fallen?\"}]},{\"step_number\":4,\"key\":\"reframe\",\"inputs\":[{\"field_key\":\"alt_explanations\",\"prompt\":\"Write at least 3 other explanations that also fit the facts.\",\"type\":\"multi_entry\",\"min_entries\":3},{\"field_key\":\"one_more_explanation\",\"prompt\":\"Can you think of one explanation that has nothing to do with the quality of your product?\"}],\"reference_example\":[\"Demand may be lower because of seasonal changes.\",\"A new competitor may have entered the market.\",\"Customers may not know about recent improvements to the product.\",\"Marketing activity may have decreased.\",\"Economic conditions may have affected customer spending.\"]},{\"step_number\":5,\"key\":\"intervention\",\"reminder\":\"There isn\'t always a perfect action.\\nThere is usually one reasonable action based on the evidence available.\",\"inputs\":[{\"field_key\":\"action\",\"prompt\":\"Based on the evidence available, what is one thoughtful action you can take?\"}],\"reference_example\":\"Instead of immediately changing the product, gather more information.\\nReview sales data, speak with customers, compare previous months, and identify patterns before deciding what action to take.\"},{\"step_number\":6,\"key\":\"internalize\",\"inputs\":[{\"field_key\":\"principle\",\"prompt\":\"Complete this sentence: \\\"Today I learned that...\\\"\"}],\"reference_example\":\"The first explanation that comes to mind isn\'t always the correct one. Good judgment requires looking for evidence that both supports and challenges my conclusion.\"}],\"closing_reflection\":{\"prompt\":\"Where else in my life have I accepted one explanation without looking for alternatives?\",\"journal_input\":{\"field_key\":\"journal\",\"prompt\":\"Optional journal entry — user may type or speak a personal reflection here (not scored).\",\"required\":false}}}', `updated_at` = '2026-09-25 16:36:12';

INSERT INTO `foundation_days` (`day_number`, `phase`, `title`, `domain`, `primary_trap`, `secondary_trap`, `content_bundle`, `created_at`, `updated_at`)
VALUES (17, 1, 'Walk Away or Continue?', 'Negotiation', 'Sunk Cost Fallacy', 'Confirmation Bias (possible)', '{\"day\":17,\"phase\":1,\"title\":\"Walk Away or Continue?\",\"domain\":\"Negotiation\",\"mission\":\"Know when persistence becomes attachment.\",\"learning_objective\":\"Choose Thoughtful Actions\",\"difficulty\":\"Intermediate\",\"emotional_intensity\":\"Moderate\",\"estimated_minutes\":\"3-5\",\"primary_skill\":\"Intervention (Third Learning Cycle)\",\"primary_trap\":\"Sunk Cost Fallacy\",\"secondary_trap\":\"Confirmation Bias (possible)\",\"scenario_text\":\"You\'ve been negotiating a business partnership for the past six weeks.\\nThere have been multiple meetings and countless phone calls.\\nEvery discussion ends with new conditions being added.\\nThe agreement still doesn\'t meet your original expectations.\\nYou begin thinking:\\n\\\"I\'ve already invested so much time. I have to make this work.\\\"\",\"steps\":[{\"step_number\":1,\"key\":\"detect\",\"insight\":\"Time already spent cannot be recovered.\\nThe next decision should depend on what creates the most value going forward.\",\"inputs\":[{\"field_key\":\"facts\",\"prompt\":\"Write only the facts.\",\"multiline\":true},{\"field_key\":\"story\",\"prompt\":\"Now write the story your mind is creating.\",\"multiline\":true}],\"reference_example\":\"Fact: I\'ve spent six weeks negotiating, and the agreement still doesn\'t meet my expectations.\\nStory: I can\'t walk away now because all that effort will be wasted.\"},{\"step_number\":2,\"key\":\"decode\",\"prompt\":\"Which thinking trap is most likely at work?\",\"input_type\":\"single_choice\",\"options\":[{\"key\":\"sunk_cost\",\"label\":\"Sunk Cost Fallacy\",\"definition\":\"Continuing a course of action because of past investment rather than future value.\"},{\"key\":\"confirmation_bias\",\"label\":\"Confirmation Bias\",\"definition\":\"Only seeing details that confirm the feared story.\"},{\"key\":\"validation_seeking\",\"label\":\"Validation Seeking\",\"definition\":\"Heavy reliance on immediate external acknowledgment.\"}],\"correct_option_key\":\"sunk_cost\",\"explanation_reveal\":\"after_selection\",\"explanation\":\"Why Sunk Cost Fallacy.\\nYour decision is becoming driven by the effort you\'ve already invested rather than by whether the partnership still makes sense.\\nPast effort is real.\\nIt shouldn\'t automatically decide your future.\"},{\"step_number\":3,\"key\":\"reality_check\",\"tip\":\"Ask yourself, \\\"Would I make the same decision if I were starting today?\\\"\",\"inputs\":[{\"field_key\":\"q1\",\"prompt\":\"1. What fact do you know for certain?\"},{\"field_key\":\"q2\",\"prompt\":\"2. What are you assuming?\"},{\"field_key\":\"q3\",\"prompt\":\"3. If these negotiations started today, would you still pursue this opportunity?\"},{\"field_key\":\"q4\",\"prompt\":\"4. What benefits still exist if you continue?\"},{\"field_key\":\"q5\",\"prompt\":\"5. What risks exist if you continue simply because you\'ve already invested time?\"}]},{\"step_number\":4,\"key\":\"reframe\",\"inputs\":[{\"field_key\":\"alt_explanations\",\"prompt\":\"Write at least 3 other explanations that also fit the facts.\",\"type\":\"multi_entry\",\"min_entries\":3},{\"field_key\":\"one_more_explanation\",\"prompt\":\"Can you think of one benefit of saying \\\"no\\\" instead of continuing?\"}],\"reference_example\":[\"Walking away may create space for a better opportunity.\",\"Continuing only makes sense if the future benefits justify it.\",\"Renegotiating the terms may be a better option.\",\"Time already invested is a learning experience, not a reason to continue.\"]},{\"step_number\":5,\"key\":\"intervention\",\"reminder\":\"There isn\'t always a perfect action.\\nThere is usually one reasonable action based on the evidence available.\",\"inputs\":[{\"field_key\":\"action\",\"prompt\":\"Based on the evidence available, what is one thoughtful action you can take?\"}],\"reference_example\":\"Review the agreement against your original objectives.\\nIf the revised terms no longer meet your goals, be prepared to respectfully end the negotiation rather than continuing simply because of the time already invested.\"},{\"step_number\":6,\"key\":\"internalize\",\"inputs\":[{\"field_key\":\"principle\",\"prompt\":\"Complete this sentence: \\\"Today I learned that...\\\"\"}],\"reference_example\":\"Good judgment isn\'t about protecting past effort. It\'s about making the best decision with the information I have today.\"}],\"closing_reflection\":{\"prompt\":\"What am I continuing today mainly because of what I\'ve already invested, rather than because it still makes sense?\",\"journal_input\":{\"field_key\":\"journal\",\"prompt\":\"Optional journal entry — user may type or speak a personal reflection here (not scored).\",\"required\":false}}}', '2026-09-25 16:36:12', '2026-09-25 16:36:12')
